int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n;
    if (!(cin >> n)) return 0;

    int dario_wins = 0;
    int xerxes_wins = 0;

    for (int i = 0; i < n; ++i) {
        int d, x;
        cin >> d >> x;
        // Dario vence se x for (d + 1) % 5 ou (d + 2) % 5
        if (x == (d + 1) % 5 || x == (d + 2) % 5) {
            dario_wins++;
        } else {
            xerxes_wins++;
        }
    }

    if (dario_wins > xerxes_wins) {
        cout << "dario\n";
    } else {
        cout << "xerxes\n";
    }

    return 0;
}
